window.docContents[32].resolve({"/#Functional-Programming-in-Lean--Monad-Transformers--Summary--do--Notation-for-Monad-Transformers":{"contents":"Lean's do-blocks support early return, in which the block is terminated with some value, locally mutable variables, for-loops with break and continue, and single-branched if-statements.\nWhile this may seem to be introducing imperative features that would get in the way of using Lean to write proofs, it is in fact nothing more than a more convenient syntax for certain common uses of monad transformers.\nBehind the scenes, whatever monad the do-block is written in is transformed by appropriate uses of  and  to support these additional effects.\n\n\n","context":"Functional Programming in Lean\u0009Monad Transformers\u0009Summary","header":"6.6.4. do -Notation for Monad Transformers","id":"/#Functional-Programming-in-Lean--Monad-Transformers--Summary--do--Notation-for-Monad-Transformers"}});